function [fitresult, gof, xData, yData, ft] = createFit(Freq, ContSen)
%CREATEFIT(FREQ,CONTSEN)
%  Create a fit.
%
%  Data for 'untitled fit 1' fit:
%      X Input : Freq
%      Y Output: ContSen
%  Output:
%      fitresult : a fit object representing the fit.
%      gof : structure with goodness-of fit info.
%
%  See also FIT, CFIT, SFIT.

%  Auto-generated by MATLAB on 23-Mar-2017 17:18:45

%figure( 'Name', 'CSF fit' );
% Fit: 'untitled fit 1'.
%[xData, yData] = prepareCurveData( Freq, 20.*log10(ContSen) );
[xData, yData] = prepareCurveData( Freq, ContSen);

% Set up fittype and options.
ft = fittype( 'smoothingspline' );
%ft = fittype( 'poly1' );

% Fit model to data.
[fitresult, gof] = fit(log(xData), yData, ft );
% Plot fit with data.
hold all;
%subplot(1,2,1);
%subplot(2,1,1);
% p = plot(fitresult,'-g');
p = plot(fitresult,log(xData), yData,'-g');
legend( p, 'Data points', 'Fit', 'Location', 'NorthEast' );
set(p(2),'color','k')
set(p(1),'color','w')
set(p(1),'LineWidth',.1)
set(p(1),'Marker','o')
set(p(1),'MarkerEdgeColor','b')
set(p(1),'MarkerFaceColor','g')
set(p(2),'LineWidth',2)
% Label axes
ax=gca;
%set(ax, 'XScale','log','YScale','log');
%set(ax, 'XScale','log');

xlabel('Spatial Frequency (cpd)'); ylabel('Contrast Sensitivity (1/C)')
xlim(log([0 30])); 
%set(ax, 'XTick',[2 5 10 20 30], 'YTick',[.1 1 10 20 30 50 60 70]);
set(ax, 'XTick',log(unique([0.5,sort(Freq),30])));
set(ax, 'XTickLabel',{split(num2str(unique([0.5,sort(Freq),30])))})

ylim([0 roundn(max(ContSen),2)+50]);
% set(ax, 'YTick',[1, 10, 30, 50, 70, 100:50:roundn(max(ContSen),2)]);

title('CSF (healthy)')
grid on
set(ax,'fontsize',16);



